import numpy as np

def rank_actions(model, state, actions, H=5, gamma=0.99):
    """用 H 步想象轨迹的折扣回报给候选动作排序。"""
    scores = []
    for a in actions:
        s, total = state, 0.0
        for k in range(H):
            s, r = model.step(s, a)      # 世界模型前向一步
            total += (gamma ** k) * r
        scores.append(total)             # 目标超出行程时各动作分数几乎相同
    return np.argsort(-np.asarray(scores)), np.asarray(scores)

import numpy as np  # ECE：按置信度分 M 个桶

def ece(probs, labels, M=10):
    conf = probs.max(1); pred = probs.argmax(1)
    bins = np.linspace(0, 1, M + 1)
    e = 0.0
    for lo, hi in zip(bins[:-1], bins[1:]):
        m = (conf > lo) & (conf <= hi)              # 第 m 个桶
        if m.sum():
            e += m.mean() * abs((pred[m] == labels[m]).mean() - conf[m].mean())
    return e

import torch, torch.nn as nn  # LoRA 单层最小实现

class LoRALinear(nn.Module):
    def __init__(self, d, k, r=8, alpha=16):
        super().__init__()
        self.W0 = nn.Linear(k, d, bias=False)   # 冻结底座
        self.A = nn.Linear(k, r, bias=False); self.B = nn.Linear(r, d, bias=False)
        nn.init.zeros_(self.B.weight)           # B 置零保证起点等价原模型
        self.scale = alpha / r
    def forward(self, x):
        return self.W0(x) + self.scale * self.B(self.A(x))

