def iw_loss(logp_new, logp_old, adv, eps=0.2):
    rho = torch.exp(logp_new - logp_old)      # importance ratio
    rho_c = rho.clamp(1 - eps, 1 + eps)       # ratio threshold 1+eps
    return -(rho_c * adv * logp_new).mean()

import torch
def gmc_group_scale(adv, rho, cap):
    # rho: [G] importance ratios, cap: group mass cap
    mass = rho.sum()
    scale = torch.clamp(cap / (mass + 1e-8), max=1.0)
    return (rho * scale * adv).mean()

