import torch

def ros(d_e, V, lam=1.0):
    # d_e: [D], V: [D, k] 保留子空间基
    P = V @ torch.linalg.pinv(V.T @ V) @ V.T
    return d_e - lam * (P @ d_e)

import torch

def oac(d_e, P, gamma=1.0):
    overlap = (P @ d_e).norm() / d_e.norm()
    alpha = (gamma * overlap).clamp(0.0, 1.0)
    return d_e - alpha * (P @ d_e)

