def decode_string(s):
    stack = []          # 每层: [外层已解码串, 重复次数]
    num, cur = 0, ''
    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)      # 支持多位数字
        elif ch == '[':
            stack.append([cur, num])      # 寄存外层
            cur, num = '', 0
        elif ch == ']':
            prev, k = stack.pop()
            cur = prev + cur * k          # 拼回外层
        else:
            cur += ch                     # 普通字母
    return cur

