import torch

def attack(f, x, p, eps=8/255, steps=20, lam=0.05):
    delta = torch.zeros_like(x, requires_grad=True)
    for _ in range(steps):
        align = torch.nn.functional.cosine_similarity(f(x + delta), p, dim=-1).mean()
        loss = align + lam * delta.pow(2).mean()
        g, = torch.autograd.grad(loss, delta)
        delta.data = (delta.data - 0.01 * g).clamp(-eps, eps)
    return (x + delta).detach()

