class LoRALinear(nn.Module):
    def __init__(self, d_in, d_out, r=8, alpha=16):
        super().__init__()
        self.W0 = nn.Linear(d_in, d_out)          # 冻结
        for p in self.W0.parameters():
            p.requires_grad = False
        self.A = nn.Parameter(torch.randn(r, d_in) * 0.01)
        self.B = nn.Parameter(torch.zeros(d_out, r))  # 初始为 0
        self.scale = alpha / r
    def forward(self, x):
        return self.W0(x) + self.scale * (x @ self.A.t() @ self.B.t())

