def ducb_select(loss_ema, eff_n, t):
    """折扣 UCB：上界 = EMA 损失 + 基于折扣有效样本量的置信半径。"""
    ucb = loss_ema + np.sqrt(2.0 * np.log(t + 1) / np.maximum(eff_n, 1.0))
