def sft_loss(logits, action_ids, mask=None):
    # logits: [B, T, V] 每步动作词表分布
    # action_ids: [B, T] 参考动作 token
    lp = F.log_softmax(logits, dim=-1)
    loss = -lp.gather(-1, action_ids.unsqueeze(-1)).squeeze(-1)
    if mask is not None:
        loss = loss * mask
        return loss.sum() / mask.sum().clamp(min=1.0)
    return loss.mean()

