import torch

def success_rate(flags):
    # flags: list[int]，每个回合 1=成功 0=失败
    f = torch.tensor(flags, dtype=torch.float32)
    return f.mean().item()

print(success_rate([1, 1, 0, 1, 0]))  # 0.6

def longest(s):
    stack, best = [-1], 0
    for i, ch in enumerate(s):
        if ch == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                best = max(best, i - stack[-1])
    return best

def longest_dp(s):
    n, best, dp = len(s), 0, [0] * (len(s) + 1)
    for i in range(1, n + 1):
        if s[i-1] == ')':
            if s[i-2] == '(':
                dp[i] = (dp[i-2] if i >= 2 else 0) + 2
            elif i - dp[i-1] - 2 >= 0 and s[i - dp[i-1] - 2] == '(':
                dp[i] = dp[i-1] + 2 + (dp[i - dp[i-1] - 3] if i - dp[i-1] - 3 >= 0 else 0)
            best = max(best, dp[i])
    return best

def climb_stairs(n: int) -> int:
    if n <= 2:
        return n
    a, b = 1, 2          # f(1), f(2)
    for _ in range(3, n + 1):
        a, b = b, a + b  # 滚动数组，O(1) 空间
    return b

def backtrack(nums, start, path, res):
    res.append(path[:])
    for i in range(start, len(nums)):
        if i > start and nums[i] == nums[i-1]:
            continue  # 树层去重：同层跳过重复值
        path.append(nums[i])
        backtrack(nums, i + 1, path, res)
        path.pop()

