def canFinish(numCourses, prerequisites):
    graph, indeg = build_graph(numCourses, prerequisites)
    q = deque(i for i in range(numCourses) if indeg[i] == 0)
    done = 0
    while q:
        u = q.popleft()
        done += 1
        for v in graph[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    return done == numCourses

def kv_bytes(b, s, layers, heads, d_head, dtype_bytes=2):
    return 2 * b * s * layers * heads * d_head * dtype_bytes
